def nxt(t):
    import re
    m=re.match(r'([A-Z])([A-Z])(\d+)',t)
    return m.group(1),m.group(2),int(m.group(3))
s=['AH21','CJ18','EL15','GN12']
a,b,n=nxt(s[-1])
ans=chr(ord(a)+2)+chr(ord(b)+2)+str(n-3)
opts={'A':'HR11','B':'IP9','C':'J8','D':'HQ10'}
assert ans==opts['B']
for k in 'ACD': assert ans!=opts[k]

