def swap(e,a,b):
    toks=re.findall(r'\d+(?:\.\d+)?|\D',e)
    return ''.join(b if t==a else a if t==b else t for t in toks)
def ev(e):
    return eval(re.sub(r'(\d+(?:\.\d+)?)',r'F("\1")',e))
res={k:ev(swap(num,a,b))/ev(swap(den,a,b)) for k,(a,b) in opts.items()}
good=[k for k,v in res.items() if v==2]
assert good==['B'], res

