s=[('mountain stand tall','33 66 44'),('rocky is tall','44 55 11'),('rocky is mountain','33 55 11')]
cand={}
for w in set(' '.join(x for x,_ in s).split()):
    c=None
    for words,codes in s:
        if w in words.split():
            c=set(codes.split()) if c is None else c&set(codes.split())
    for words,codes in s:
        if w not in words.split(): c-=set(codes.split())
    cand[w]=c
assert cand['stand']=={'66'}
opts={'A':'33','B':'11','C':'44','D':'66'}
fit=[k for k,v in opts.items() if {v}==cand['stand']]
assert fit==['D']

